-- Users and refresh-token storage for authentication.
-- IDs are UUIDs generated by the application (Hibernate), so the tables have no ID defaults.

create table users (
    id            uuid         primary key,
    -- The application stores email addresses trimmed and in lower case. The check keeps it that way,
    -- so the unique constraint also rejects "Alice@Example.com" when "alice@example.com" exists.
    email         varchar(254) not null,
    password_hash varchar(255) not null,
    display_name  varchar(100) not null,
    created_at    timestamptz  not null,
    updated_at    timestamptz  not null,
    constraint users_email_key unique (email),
    constraint users_email_normalized check (email = lower(btrim(email))),
    constraint users_password_hash_not_empty check (password_hash <> ''),
    constraint users_display_name_not_blank check (btrim(display_name) <> ''),
    constraint users_updated_after_created check (updated_at >= created_at)
);

-- One row per login session. Logging in starts a family; every refresh token issued by rotating
-- that session's tokens belongs to the same family, so the whole session can be revoked at once.
create table refresh_token_families (
    id             uuid        primary key,
    user_id        uuid        not null references users (id) on delete cascade,
    created_at     timestamptz not null,
    revoked_at     timestamptz,
    revoked_reason varchar(32),
    constraint refresh_token_families_revocation_complete check ((revoked_at is null) = (revoked_reason is null)),
    constraint refresh_token_families_revoked_reason_valid check (revoked_reason in ('LOGOUT', 'REUSE_DETECTED'))
);

create index refresh_token_families_user_id_idx on refresh_token_families (user_id);

create table refresh_tokens (
    id         uuid        primary key,
    family_id  uuid        not null references refresh_token_families (id) on delete cascade,
    -- Hex-encoded SHA-256 hash of the token. The raw token is never stored.
    token_hash varchar(64) not null,
    created_at timestamptz not null,
    expires_at timestamptz not null,
    -- Set when the token is exchanged for a new one (rotation) or its session is logged out.
    revoked_at timestamptz,
    constraint refresh_tokens_token_hash_key unique (token_hash),
    constraint refresh_tokens_token_hash_format check (token_hash ~ '^[0-9a-f]{64}$'),
    constraint refresh_tokens_expires_after_created check (expires_at > created_at)
);

create index refresh_tokens_family_id_idx on refresh_tokens (family_id);
